def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    me = [h[0] for h in history]
    op = [h[1] for h in history]
    op_c = op.count('C')
    op_d = n - op_c
    last_op = op[-1]

    # Last-run of opponent action
    run = 0
    for i in range(n - 1, -1, -1):
        if op[i] == last_op:
            run += 1
        else:
            break

    # Opponent always defects -> defect
    if op_c == 0:
        return 'D'

    # Opponent always cooperates -> cooperate to keep mutual CC, exploit only at very end
    if op_d == 0:
        if n >= 99:
            return 'D'
        return 'C'

    # Very persistent defection -> defect
    if op_d * 4 >= n * 3:
        return 'D'

    # If opponent just defected:
    if last_op == 'D':
        # Long defection runs: punish but attempt occasional reconciliation
        if run >= 4:
            if rng.random() < 0.12:
                return 'C'
            return 'D'
        if run >= 2:
            return 'D'
        # Single recent defection:
        # If opponent is otherwise very cooperative, punish once then resume
        if op_c * 5 >= n * 4:
            if me[-1] == 'D':
                return 'C'
            return 'D'
        # Mixed opponent: retaliate
        if op_d * 2 > n:
            return 'D'
        # Mild retaliation
        if me[-1] == 'D':
            return 'C'
        return 'D'

    # Opponent just cooperated.
    # If we are in a retaliation sequence, return to cooperation.
    if me[-1] == 'D':
        if op_c * 4 >= n * 3:
            return 'C'
        # If opponent still mostly defects, keep punishing
        if op_d * 2 > n:
            if rng.random() < 0.3:
                return 'C'
            return 'D'
        return 'C'

    # Both cooperated recently.
    # Endgame exploitation against highly cooperative opponents.
    if n >= 95 and op_c * 4 >= n * 3:
        return 'D'

    # Mid-game probing against very cooperative opponents.
    if op_c * 5 >= n * 4:
        if n >= 20 and n % 19 == 0 and rng.random() < 0.5:
            return 'D'
        return 'C'

    # Mixed opponent: cooperate if recent behavior is decent, else defect.
    recent = op[-6:]
    recent_c = recent.count('C')
    if recent_c >= 4:
        return 'C'
    if recent_c <= 1:
        return 'D'

    # Tit-for-tat-ish forgiveness
    if op[-1] == 'C':
        return 'C'
    return 'D'
